import{_ as n,C as r,o as s,c as d,j as a,a as i,b as h,w as t,E as l,a2 as c,a3 as p}from"./chunks/framework.pb1iZPmZ.js";const q=JSON.parse('{"title":"Step 10: Comprehensive 150+ Interview Questions & Answers","description":"","frontmatter":{},"headers":[],"relativePath":"09-interview-qa.md","filePath":"09-interview-qa.md"}'),u={name:"09-interview-qa.md"};function k(g,e,m,f,y,b){const o=r("Mermaid");return s(),d("div",null,[e[1]||(e[1]=a("h1",{id:"step-10-comprehensive-150-interview-questions-answers",tabindex:"-1"},[i("Step 10: Comprehensive 150+ Interview Questions & Answers "),a("a",{class:"header-anchor",href:"#step-10-comprehensive-150-interview-questions-answers","aria-label":'Permalink to "Step 10: Comprehensive 150+ Interview Questions & Answers"'},"​")],-1)),(s(),h(c,null,{default:t(()=>[l(o,{id:"mermaid-3",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20QA%5B%22150%2B%20Interview%20Questions%20%26%20Answers%22%5D%0A%20%20%20%20QA%20--%3E%20G1%5B%22Group%201%3A%20Project%20Overview%20%26%20Architecture%20(Q1%20-%20Q25)%22%5D%0A%20%20%20%20QA%20--%3E%20G2%5B%22Group%202%3A%20Core%20JavaScript%20%26%20Node.js%20Fundamentals%20(Q26%20-%20Q50)%22%5D%0A%20%20%20%20QA%20--%3E%20G3%5B%22Group%203%3A%20Express%20Backend%20%26%20Middleware%20(Q51%20-%20Q75)%22%5D%0A%20%20%20%20QA%20--%3E%20G4%5B%22Group%204%3A%20Database%20%26%20Session%20Persistence%20(Q76%20-%20Q100)%22%5D%0A%20%20%20%20QA%20--%3E%20G5%5B%22Group%205%3A%20Authentication%2C%20Security%20%26%20OWASP%20(Q101%20-%20Q125)%22%5D%0A%20%20%20%20QA%20--%3E%20G6%5B%22Group%206%3A%20Frontend%2C%20Performance%20%26%20Systems%20(Q126%20-%20Q150%2B)%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=p('<hr><h2 id="group-1-project-overview-high-level-architecture-q1-–-q25" tabindex="-1">Group 1: Project Overview &amp; High-Level Architecture (Q1 – Q25) <a class="header-anchor" href="#group-1-project-overview-high-level-architecture-q1-–-q25" aria-label="Permalink to &quot;Group 1: Project Overview &amp; High-Level Architecture (Q1 – Q25)&quot;">​</a></h2><h3 id="q1-walk-me-through-your-project-in-3-minutes" tabindex="-1">Q1: Walk me through your project in 3 minutes. <a class="header-anchor" href="#q1-walk-me-through-your-project-in-3-minutes" aria-label="Permalink to &quot;Q1: Walk me through your project in 3 minutes.&quot;">​</a></h3><blockquote><p>&quot;The Sachidanand Member Access Portal is a full-stack authentication gateway designed for healthcare and hospital staff to access protected internal clinical dashboards. I built the backend on Node.js 22 and Express 5, using MongoDB and Mongoose for durable data storage.</p><p>On the frontend, instead of shipping a heavy React single-page app for a simple login interface, I implemented an interactive glassmorphic UI using pure CSS3 and a custom 3D mouse parallax tilt engine in vanilla JavaScript. The card tracks cursor movement relative to the viewport center and applies GPU-accelerated CSS transforms.</p><p>For authentication, I chose stateful server sessions backed by <code>connect-mongo</code>. When an employee signs in with valid credentials, Express establishes a session in MongoDB with a twenty-four-hour time-to-live index and issues a signed HMAC cookie to the browser. A global hydration middleware intercepts authenticated requests, fetches the employee document from MongoDB, and populates <code>res.locals.user</code>. Protected routes like <code>/dashboard</code> enforce authorization guards before rendering dynamic server-side EJS templates.</p><p>When the staff member signs out, the server executes <code>req.session.destroy()</code>, commanding MongoDB to delete the session document immediately. This provides instant revocation, which is critical in shared hospital environments. Overall, the project demonstrates clean layered architecture, stateful session lifecycle management, and high-performance client-side DOM animations.&quot;</p></blockquote><h3 id="q2-what-exact-problem-does-this-application-solve" tabindex="-1">Q2: What exact problem does this application solve? <a class="header-anchor" href="#q2-what-exact-problem-does-this-application-solve" aria-label="Permalink to &quot;Q2: What exact problem does this application solve?&quot;">​</a></h3><p>It provides perimeter identity verification and stateful session control for hospital staff (&quot;Sachidanand Health&quot;), preventing unauthorized public access to clinical dashboards while enabling immediate session invalidation on shared hospital terminals.</p><h3 id="q3-what-architectural-pattern-does-this-codebase-follow" tabindex="-1">Q3: What architectural pattern does this codebase follow? <a class="header-anchor" href="#q3-what-architectural-pattern-does-this-codebase-follow" aria-label="Permalink to &quot;Q3: What architectural pattern does this codebase follow?&quot;">​</a></h3><p>Classic Model-View-Controller (MVC) monolithic layered pattern:</p><ul><li><strong>Model</strong>: Mongoose <code>User</code> schema mapped to the <code>employees</code> collection in <code>hospital_login</code>, plus <code>connect-mongo</code> managing <code>sessions</code>.</li><li><strong>View</strong>: Static HTML5 (<code>login.html</code>) for the public portal and Server-Side Rendered EJS (<code>views/dashboard.ejs</code>) for authenticated views.</li><li><strong>Controller</strong>: Express route handlers in <code>app.js</code> (<code>POST /signup</code>, <code>POST /login</code>, <code>GET /dashboard</code>, <code>POST /logout</code>).</li></ul><h3 id="q4-why-did-you-choose-stateful-sessions-over-stateless-jwts" tabindex="-1">Q4: Why did you choose stateful sessions over stateless JWTs? <a class="header-anchor" href="#q4-why-did-you-choose-stateful-sessions-over-stateless-jwts" aria-label="Permalink to &quot;Q4: Why did you choose stateful sessions over stateless JWTs?&quot;">​</a></h3><p>In healthcare, instant session revocation is a non-negotiable security requirement. If a clinician leaves a computer unattended or an employee badge is revoked, stateful sessions allow the administrator or user to delete the session document in MongoDB immediately. With stateless JWTs, a token remains valid until its cryptographic expiration timestamp unless you build a complex distributed blacklist in Redis, which defeats the purpose of being stateless.</p><h3 id="q5-why-is-connect-mongo-necessary-why-not-use-express-s-default-session-store" tabindex="-1">Q5: Why is <code>connect-mongo</code> necessary? Why not use Express&#39;s default session store? <a class="header-anchor" href="#q5-why-is-connect-mongo-necessary-why-not-use-express-s-default-session-store" aria-label="Permalink to &quot;Q5: Why is `connect-mongo` necessary? Why not use Express&#39;s default session store?&quot;">​</a></h3><p>Express&#39;s default session store is <code>MemoryStore</code>, which saves sessions in the Node.js process&#39;s heap RAM. <code>MemoryStore</code> suffers from three critical flaws:</p><ol><li>It leaks memory over time.</li><li>It cannot scale across multiple CPU cores or clustered server instances because memory is not shared.</li><li>Every time the server restarts or reloads, all active logged-in users are forcefully logged out. <code>connect-mongo</code> persists session documents to MongoDB, allowing sessions to survive restarts and be shared across multiple backend server replicas.</li></ol><h3 id="q6-how-does-express-5-differ-from-express-4-in-this-project" tabindex="-1">Q6: How does Express 5 differ from Express 4 in this project? <a class="header-anchor" href="#q6-how-does-express-5-differ-from-express-4-in-this-project" aria-label="Permalink to &quot;Q6: How does Express 5 differ from Express 4 in this project?&quot;">​</a></h3><p>In Express 4, if an asynchronous route handler (<code>async (req, res) =&gt; ...</code>) rejected a Promise or threw an unhandled error, the request would hang indefinitely unless wrapped in a manual <code>try/catch</code> block that called <code>next(err)</code>. Express 5 natively catches rejected Promises in route handlers and middleware, routing them directly to Express&#39;s built-in error-handling pipeline.</p><h3 id="q7-where-are-static-files-served-from-in-this-application" tabindex="-1">Q7: Where are static files served from in this application? <a class="header-anchor" href="#q7-where-are-static-files-served-from-in-this-application" aria-label="Permalink to &quot;Q7: Where are static files served from in this application?&quot;">​</a></h3><p>Line 26 of <code>app.js</code> declares <code>app.use(express.static(path.join(__dirname, &#39;public&#39;)))</code>. Express serves static assets (CSS, client JS, images) from the <code>public/</code> directory before requests hit the route handlers.</p><h3 id="q8-what-is-the-purpose-of-user-json-in-the-root-repository" tabindex="-1">Q8: What is the purpose of <code>user.json</code> in the root repository? <a class="header-anchor" href="#q8-what-is-the-purpose-of-user-json-in-the-root-repository" aria-label="Permalink to &quot;Q8: What is the purpose of `user.json` in the root repository?&quot;">​</a></h3><p><code>user.json</code> contains mock seed data with bcrypt hashed passwords (<code>$2b$10$...</code>). It serves as a reference fixture demonstrating how hashed credentials look when migrated from prototype plaintext to enterprise storage.</p><h3 id="q9-what-happens-when-an-unauthenticated-user-attempts-to-visit-get-dashboard" tabindex="-1">Q9: What happens when an unauthenticated user attempts to visit <code>GET /dashboard</code>? <a class="header-anchor" href="#q9-what-happens-when-an-unauthenticated-user-attempts-to-visit-get-dashboard" aria-label="Permalink to &quot;Q9: What happens when an unauthenticated user attempts to visit `GET /dashboard`?&quot;">​</a></h3><p>In <code>app.js:112</code>, the route guard evaluates: <code>if (!req.session.userId) return res.redirect(&#39;/login&#39;);</code>. The server intercepts the request and issues an HTTP 302 Found redirect, routing the browser back to <code>/login</code>.</p><h3 id="q10-what-happens-when-an-already-authenticated-user-visits-get-login" tabindex="-1">Q10: What happens when an already authenticated user visits <code>GET /login</code>? <a class="header-anchor" href="#q10-what-happens-when-an-already-authenticated-user-visits-get-login" aria-label="Permalink to &quot;Q10: What happens when an already authenticated user visits `GET /login`?&quot;">​</a></h3><p>In <code>app.js:53</code>, the route evaluates: <code>if (req.session.userId) return res.redirect(&#39;/dashboard&#39;);</code>. It immediately forwards the authenticated user to their dashboard, preventing redundant logins.</p><h3 id="q11-explain-the-purpose-of-res-locals-in-express" tabindex="-1">Q11: Explain the purpose of <code>res.locals</code> in Express. <a class="header-anchor" href="#q11-explain-the-purpose-of-res-locals-in-express" aria-label="Permalink to &quot;Q11: Explain the purpose of `res.locals` in Express.&quot;">​</a></h3><p><code>res.locals</code> is an object scoped to the lifetime of a single HTTP request. Variables attached to <code>res.locals</code> are automatically available to all EJS templates rendered during that request. In <code>app.js:43</code>, our hydration middleware sets <code>res.locals.user</code>, allowing <code>dashboard.ejs</code> to access <code>user.name</code> without explicitly passing it in every <code>res.render</code> call.</p><h3 id="q12-why-is-the-views-directory-setting-required-in-app-js" tabindex="-1">Q12: Why is the views directory setting required in <code>app.js</code>? <a class="header-anchor" href="#q12-why-is-the-views-directory-setting-required-in-app-js" aria-label="Permalink to &quot;Q12: Why is the views directory setting required in `app.js`?&quot;">​</a></h3><p>Line 39 specifies <code>app.set(&#39;views&#39;, path.join(__dirname, &#39;views&#39;))</code>. This instructs Express where to search for template files when <code>res.render(&#39;dashboard&#39;)</code> is called. Without this directory and file existing, Express throws a <code>Failed to lookup view</code> 500 error.</p><h3 id="q13-why-is-extended-true-passed-to-bodyparser-urlencoded" tabindex="-1">Q13: Why is <code>extended: true</code> passed to <code>bodyParser.urlencoded()</code>? <a class="header-anchor" href="#q13-why-is-extended-true-passed-to-bodyparser-urlencoded" aria-label="Permalink to &quot;Q13: Why is `extended: true` passed to `bodyParser.urlencoded()`?&quot;">​</a></h3><p><code>extended: true</code> configures <code>body-parser</code> to use the <code>qs</code> library rather than the native <code>querystring</code> library. This allows parsing of rich, nested objects and arrays encoded in URL query format.</p><h3 id="q14-how-does-mongodb-know-when-to-expire-old-sessions" tabindex="-1">Q14: How does MongoDB know when to expire old sessions? <a class="header-anchor" href="#q14-how-does-mongodb-know-when-to-expire-old-sessions" aria-label="Permalink to &quot;Q14: How does MongoDB know when to expire old sessions?&quot;">​</a></h3><p><code>connect-mongo</code> automatically creates a MongoDB <strong>Time-To-Live (TTL) index</strong> on the <code>expires</code> field of documents in the <code>sessions</code> collection. A background thread inside MongoDB checks this index every 60 seconds and permanently purges documents whose expiration timestamp has passed.</p><h3 id="q15-what-is-the-port-configuration-of-this-server" tabindex="-1">Q15: What is the port configuration of this server? <a class="header-anchor" href="#q15-what-is-the-port-configuration-of-this-server" aria-label="Permalink to &quot;Q15: What is the port configuration of this server?&quot;">​</a></h3><p>Line 9 sets <code>const port = 3000;</code>, causing Express to listen for incoming TCP connections on <code>http://localhost:3000</code>.</p><h3 id="q16-what-database-connection-string-is-used" tabindex="-1">Q16: What database connection string is used? <a class="header-anchor" href="#q16-what-database-connection-string-is-used" aria-label="Permalink to &quot;Q16: What database connection string is used?&quot;">​</a></h3><p>Line 12 sets <code>const dbUrl = &#39;mongodb://localhost:27017/hospital_login&#39;;</code>, targeting the local MongoDB daemon on standard port 27017 and database <code>hospital_login</code>.</p><h3 id="q17-what-collection-is-the-mongoose-user-model-mapped-to" tabindex="-1">Q17: What collection is the Mongoose <code>User</code> model mapped to? <a class="header-anchor" href="#q17-what-collection-is-the-mongoose-user-model-mapped-to" aria-label="Permalink to &quot;Q17: What collection is the Mongoose `User` model mapped to?&quot;">​</a></h3><p>In <code>app.js:22</code>, the schema explicitly passes <code>{ collection: &#39;employees&#39; }</code>. This overrides Mongoose&#39;s default pluralization convention (which would have been <code>users</code>) and stores documents in the <code>employees</code> collection.</p><h3 id="q18-what-are-the-three-fields-defined-on-the-user-schema" tabindex="-1">Q18: What are the three fields defined on the <code>User</code> schema? <a class="header-anchor" href="#q18-what-are-the-three-fields-defined-on-the-user-schema" aria-label="Permalink to &quot;Q18: What are the three fields defined on the `User` schema?&quot;">​</a></h3><p>In <code>app.js:18-22</code>:</p><ol><li><code>username</code>: Required string.</li><li><code>password</code>: Required string.</li><li><code>name</code>: Optional string.</li></ol><h3 id="q19-what-is-the-cookie-lifetime-configured-on-the-session" tabindex="-1">Q19: What is the cookie lifetime configured on the session? <a class="header-anchor" href="#q19-what-is-the-cookie-lifetime-configured-on-the-session" aria-label="Permalink to &quot;Q19: What is the cookie lifetime configured on the session?&quot;">​</a></h3><p>Line 35 sets <code>cookie: { maxAge: 1000 * 60 * 60 * 24 }</code>, establishing a cookie validity window of 86,400,000 milliseconds (exactly 24 hours).</p><h3 id="q20-what-is-the-session-secret-key-in-the-code" tabindex="-1">Q20: What is the session secret key in the code? <a class="header-anchor" href="#q20-what-is-the-session-secret-key-in-the-code" aria-label="Permalink to &quot;Q20: What is the session secret key in the code?&quot;">​</a></h3><p>Line 31 sets <code>secret: &#39;your_secret_key&#39;</code>. This string is used as the HMAC cryptographic key to sign the session ID in the <code>connect.sid</code> cookie, preventing client-side tampering.</p><h3 id="q21-what-happens-if-saveuninitialized-false-is-configured" tabindex="-1">Q21: What happens if <code>saveUninitialized: false</code> is configured? <a class="header-anchor" href="#q21-what-happens-if-saveuninitialized-false-is-configured" aria-label="Permalink to &quot;Q21: What happens if `saveUninitialized: false` is configured?&quot;">​</a></h3><p>It prevents Express from saving a new, empty session to MongoDB if the session was not modified during the request. This avoids creating thousands of empty session documents for anonymous bots and visitors who simply view <code>/login</code>.</p><h3 id="q22-what-happens-if-resave-false-is-configured" tabindex="-1">Q22: What happens if <code>resave: false</code> is configured? <a class="header-anchor" href="#q22-what-happens-if-resave-false-is-configured" aria-label="Permalink to &quot;Q22: What happens if `resave: false` is configured?&quot;">​</a></h3><p>It prevents the session from being resaved to the session store if it was never modified during the request, significantly reducing database write IOPS.</p><h3 id="q23-why-is-logout-implemented-as-a-post-route-instead-of-a-get-route" tabindex="-1">Q23: Why is logout implemented as a POST route instead of a GET route? <a class="header-anchor" href="#q23-why-is-logout-implemented-as-a-post-route-instead-of-a-get-route" aria-label="Permalink to &quot;Q23: Why is logout implemented as a POST route instead of a GET route?&quot;">​</a></h3><p>HTTP GET requests must be safe and idempotent according to RFC 7231. Using GET for logout allows malicious third-party websites to trigger CSRF logouts by embedding <code>&lt;img src=&quot;http://hospital.com/logout&quot;&gt;</code>, and causes aggressive browser link pre-fetchers to accidentally terminate active clinician sessions.</p><h3 id="q24-what-is-the-damping-factor-in-the-3d-mouse-parallax-engine" tabindex="-1">Q24: What is the damping factor in the 3D mouse parallax engine? <a class="header-anchor" href="#q24-what-is-the-damping-factor-in-the-3d-mouse-parallax-engine" aria-label="Permalink to &quot;Q24: What is the damping factor in the 3D mouse parallax engine?&quot;">​</a></h3><p>In <code>login.html:463-464</code>, the cursor offset is divided by <code>25</code>. This scaling factor dampens raw pixel movements into subtle, controlled angular rotations.</p><h3 id="q25-what-angle-clamping-is-applied-to-the-3d-tilt-card" tabindex="-1">Q25: What angle clamping is applied to the 3D tilt card? <a class="header-anchor" href="#q25-what-angle-clamping-is-applied-to-the-3d-tilt-card" aria-label="Permalink to &quot;Q25: What angle clamping is applied to the 3D tilt card?&quot;">​</a></h3><p>In <code>login.html:465-466</code>, <code>Math.min(Math.max(angle, -10), 10)</code> limits card rotation to between $-10^\\circ$ and $+10^\\circ$, preventing excessive perspective distortion.</p><hr><h2 id="group-2-core-javascript-node-js-fundamentals-q26-–-q50" tabindex="-1">Group 2: Core JavaScript &amp; Node.js Fundamentals (Q26 – Q50) <a class="header-anchor" href="#group-2-core-javascript-node-js-fundamentals-q26-–-q50" aria-label="Permalink to &quot;Group 2: Core JavaScript &amp; Node.js Fundamentals (Q26 – Q50)&quot;">​</a></h2><h3 id="q26-explain-the-node-js-event-loop-in-the-context-of-post-login" tabindex="-1">Q26: Explain the Node.js Event Loop in the context of <code>POST /login</code>. <a class="header-anchor" href="#q26-explain-the-node-js-event-loop-in-the-context-of-post-login" aria-label="Permalink to &quot;Q26: Explain the Node.js Event Loop in the context of `POST /login`.&quot;">​</a></h3><p>The Node.js event loop is single-threaded. When <code>POST /login</code> arrives:</p><ol><li>The request enters the <strong>Poll phase</strong> where incoming TCP socket data is received and parsed.</li><li>The asynchronous database call <code>User.findOne({ username })</code> is handed off to libuv&#39;s thread pool and MongoDB driver sockets.</li><li>The main JavaScript thread is immediately freed to handle other incoming requests.</li><li>When MongoDB returns data, the Promise resolves and its callback is queued in the <strong>microtask queue</strong>.</li><li>The event loop executes the microtask immediately after the current script, running the password check and session assignment.</li></ol><h3 id="q27-what-is-the-difference-between-microtasks-and-macrotasks-in-node-js" tabindex="-1">Q27: What is the difference between microtasks and macrotasks in Node.js? <a class="header-anchor" href="#q27-what-is-the-difference-between-microtasks-and-macrotasks-in-node-js" aria-label="Permalink to &quot;Q27: What is the difference between microtasks and macrotasks in Node.js?&quot;">​</a></h3><p>Microtasks (Promises, <code>queueMicrotask</code>, <code>process.nextTick</code>) have higher priority and execute immediately after the currently running operation completes, before the event loop moves to the next phase. Macrotasks (<code>setTimeout</code>, <code>setInterval</code>, <code>setImmediate</code>, I/O callbacks) wait for their respective phase in the event loop.</p><h3 id="q28-how-does-async-await-work-under-the-hood-in-app-post-signup" tabindex="-1">Q28: How does <code>async/await</code> work under the hood in <code>app.post(&#39;/signup&#39;)</code>? <a class="header-anchor" href="#q28-how-does-async-await-work-under-the-hood-in-app-post-signup" aria-label="Permalink to &quot;Q28: How does `async/await` work under the hood in `app.post(&#39;/signup&#39;)`?&quot;">​</a></h3><p><code>async/await</code> is syntactic sugar over native ES6 Promises and generator functions. When the runtime hits <code>await User.findOne(...)</code>, execution of the <code>async</code> function is suspended, yielding control back to the event loop. Once the Promise settles, execution resumes at the exact line with the resolved value.</p><h3 id="q29-what-are-closures-and-where-are-they-used-in-this-project" tabindex="-1">Q29: What are closures and where are they used in this project? <a class="header-anchor" href="#q29-what-are-closures-and-where-are-they-used-in-this-project" aria-label="Permalink to &quot;Q29: What are closures and where are they used in this project?&quot;">​</a></h3><p>A closure is the combination of a function bundled together with references to its surrounding lexical environment. In <code>app.js:120</code>:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">post</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/logout&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">req</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">res</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  req.session.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">destroy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    res.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redirect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/login&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  });</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>The callback function passed to <code>destroy()</code> forms a closure over the outer <code>res</code> object, allowing it to execute <code>res.redirect(&#39;/login&#39;)</code> long after the outer function has finished executing.</p><h3 id="q30-what-is-the-difference-between-commonjs-and-es-modules" tabindex="-1">Q30: What is the difference between CommonJS and ES Modules? <a class="header-anchor" href="#q30-what-is-the-difference-between-commonjs-and-es-modules" aria-label="Permalink to &quot;Q30: What is the difference between CommonJS and ES Modules?&quot;">​</a></h3><p>This project uses <strong>CommonJS</strong> (<code>require</code> and <code>module.exports</code>), which loads modules synchronously at runtime. ES Modules (<code>import</code> and <code>export</code>) are parsed statically at compile time, enabling tree-shaking and asynchronous module loading.</p><h3 id="q31-what-is-variable-hoisting-in-javascript" tabindex="-1">Q31: What is variable hoisting in JavaScript? <a class="header-anchor" href="#q31-what-is-variable-hoisting-in-javascript" aria-label="Permalink to &quot;Q31: What is variable hoisting in JavaScript?&quot;">​</a></h3><p>Variable declarations using <code>var</code> and function declarations are hoisted to the top of their enclosing scope during the compilation phase. Variables declared with <code>let</code> and <code>const</code> (as used in <code>app.js</code>) are also hoisted but remain in a &quot;Temporal Dead Zone&quot; (TDZ) until evaluated, preventing accidental access before initialization.</p><h3 id="q32-explain-this-binding-in-javascript-arrow-functions-versus-standard-functions" tabindex="-1">Q32: Explain <code>this</code> binding in JavaScript arrow functions versus standard functions. <a class="header-anchor" href="#q32-explain-this-binding-in-javascript-arrow-functions-versus-standard-functions" aria-label="Permalink to &quot;Q32: Explain `this` binding in JavaScript arrow functions versus standard functions.&quot;">​</a></h3><p>Standard functions (<code>function() {}</code>) bind <code>this</code> dynamically depending on how the function was invoked. Arrow functions (<code>() =&gt; {}</code>, used across <code>app.js</code>) do not bind their own <code>this</code>; they inherit <code>this</code> lexically from the parent enclosing scope.</p><h3 id="q33-is-node-js-completely-single-threaded" tabindex="-1">Q33: Is Node.js completely single-threaded? <a class="header-anchor" href="#q33-is-node-js-completely-single-threaded" aria-label="Permalink to &quot;Q33: Is Node.js completely single-threaded?&quot;">​</a></h3><p>No. While the main JavaScript execution thread (the event loop) is single-threaded, Node.js uses <strong>libuv</strong>, which maintains a multi-threaded worker pool (default 4 threads) to handle asynchronous I/O operations such as file system access, DNS lookups, and cryptographic calculations.</p><h3 id="q34-what-causes-memory-leaks-in-node-js-applications" tabindex="-1">Q34: What causes memory leaks in Node.js applications? <a class="header-anchor" href="#q34-what-causes-memory-leaks-in-node-js-applications" aria-label="Permalink to &quot;Q34: What causes memory leaks in Node.js applications?&quot;">​</a></h3><p>Common causes include:</p><ol><li>Global variables that accumulate objects without being garbage collected.</li><li>Uncleaned event listeners (<code>EventEmitter.on</code>).</li><li>Retaining references inside long-lived closures.</li><li>Using an in-memory session store (<code>MemoryStore</code>) under sustained user traffic.</li></ol><h3 id="q35-what-is-the-difference-between-process-nexttick-and-setimmediate" tabindex="-1">Q35: What is the difference between <code>process.nextTick()</code> and <code>setImmediate()</code>? <a class="header-anchor" href="#q35-what-is-the-difference-between-process-nexttick-and-setimmediate" aria-label="Permalink to &quot;Q35: What is the difference between `process.nextTick()` and `setImmediate()`?&quot;">​</a></h3><p><code>process.nextTick()</code> callbacks are processed immediately after the current operation finishes, before any other I/O or timers. <code>setImmediate()</code> callbacks are queued in the <strong>Check phase</strong> of the event loop, running after I/O events have been polled.</p><h3 id="q36-how-does-node-js-garbage-collection-work" tabindex="-1">Q36: How does Node.js garbage collection work? <a class="header-anchor" href="#q36-how-does-node-js-garbage-collection-work" aria-label="Permalink to &quot;Q36: How does Node.js garbage collection work?&quot;">​</a></h3><p>V8 uses a generational garbage collector based on the &quot;Mark-and-Sweep&quot; algorithm. Memory is divided into Young Generation (short-lived objects like local request variables) and Old Generation (long-lived objects like application singletons). Objects that survive multiple young collection cycles are promoted to the old generation.</p><h3 id="q37-what-is-the-difference-between-synchronous-and-asynchronous-code-in-node-js" tabindex="-1">Q37: What is the difference between synchronous and asynchronous code in Node.js? <a class="header-anchor" href="#q37-what-is-the-difference-between-synchronous-and-asynchronous-code-in-node-js" aria-label="Permalink to &quot;Q37: What is the difference between synchronous and asynchronous code in Node.js?&quot;">​</a></h3><p>Synchronous code blocks the single execution thread until completion (e.g. <code>fs.readFileSync</code>), preventing any other network requests from being processed. Asynchronous code (e.g. <code>User.findOne</code>) delegates work to the kernel or thread pool and registers a callback, keeping the event loop unblocked.</p><h3 id="q38-what-are-node-js-buffers-and-streams" tabindex="-1">Q38: What are Node.js Buffers and Streams? <a class="header-anchor" href="#q38-what-are-node-js-buffers-and-streams" aria-label="Permalink to &quot;Q38: What are Node.js Buffers and Streams?&quot;">​</a></h3><p>Buffers are raw memory allocations outside the V8 heap used to handle binary data. Streams are interfaces for reading or writing data chunk-by-chunk (e.g. downloading files, HTTP request bodies) without buffering the entire payload into RAM at once.</p><h3 id="q39-what-is-the-node-js-cluster-module" tabindex="-1">Q39: What is the Node.js Cluster module? <a class="header-anchor" href="#q39-what-is-the-node-js-cluster-module" aria-label="Permalink to &quot;Q39: What is the Node.js Cluster module?&quot;">​</a></h3><p>The Cluster module allows a master Node process to spawn child worker processes (typically one per CPU core) that all share the same server port. This allows Node applications to utilize multi-core hardware and scale horizontal throughput.</p><h3 id="q40-what-happens-if-an-unhandled-exception-occurs-in-node-js" tabindex="-1">Q40: What happens if an unhandled exception occurs in Node.js? <a class="header-anchor" href="#q40-what-happens-if-an-unhandled-exception-occurs-in-node-js" aria-label="Permalink to &quot;Q40: What happens if an unhandled exception occurs in Node.js?&quot;">​</a></h3><p>If an error is thrown and not caught by a <code>try/catch</code> or an error-handling middleware, it bubbles up to the <code>process</code> object. If <code>process.on(&#39;uncaughtException&#39;)</code> is not defined, Node terminates the entire process with exit code 1.</p><hr><h2 id="group-3-express-backend-middleware-q51-–-q75" tabindex="-1">Group 3: Express Backend &amp; Middleware (Q51 – Q75) <a class="header-anchor" href="#group-3-express-backend-middleware-q51-–-q75" aria-label="Permalink to &quot;Group 3: Express Backend &amp; Middleware (Q51 – Q75)&quot;">​</a></h2><h3 id="q51-explain-the-express-middleware-chain-concept" tabindex="-1">Q51: Explain the Express middleware chain concept. <a class="header-anchor" href="#q51-explain-the-express-middleware-chain-concept" aria-label="Permalink to &quot;Q51: Explain the Express middleware chain concept.&quot;">​</a></h3><p>Express middleware functions are functions that have access to the request object (<code>req</code>), response object (<code>res</code>), and the next middleware function (<code>next</code>). Middleware execute sequentially in the exact order they are mounted using <code>app.use()</code>. Calling <code>next()</code> forwards control to the next middleware in line.</p><h3 id="q52-what-happens-if-a-middleware-forgets-to-call-next-or-send-a-response" tabindex="-1">Q52: What happens if a middleware forgets to call <code>next()</code> or send a response? <a class="header-anchor" href="#q52-what-happens-if-a-middleware-forgets-to-call-next-or-send-a-response" aria-label="Permalink to &quot;Q52: What happens if a middleware forgets to call `next()` or send a response?&quot;">​</a></h3><p>The HTTP connection remains open, and the client browser will spin indefinitely until the client-side TCP connection times out (typically 2 minutes).</p><h3 id="q53-explain-the-custom-hydration-middleware-in-app-js-41-48" tabindex="-1">Q53: Explain the custom hydration middleware in <code>app.js:41-48</code>. <a class="header-anchor" href="#q53-explain-the-custom-hydration-middleware-in-app-js-41-48" aria-label="Permalink to &quot;Q53: Explain the custom hydration middleware in `app.js:41-48`.&quot;">​</a></h3><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">req</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">res</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">next</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (req.session.userId) {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    res.locals.user </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> User.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">findById</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(req.session.userId);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    res.locals.user </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  next</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>This middleware intercepts every request. If an active session exists, it queries MongoDB for the user record and populates <code>res.locals.user</code>, making the employee profile accessible across all views.</p><h3 id="q54-what-is-the-difference-between-app-use-and-app-get" tabindex="-1">Q54: What is the difference between <code>app.use()</code> and <code>app.get()</code>? <a class="header-anchor" href="#q54-what-is-the-difference-between-app-use-and-app-get" aria-label="Permalink to &quot;Q54: What is the difference between `app.use()` and `app.get()`?&quot;">​</a></h3><p><code>app.use()</code> matches all HTTP methods (GET, POST, PUT, DELETE) and matches paths prefix-style (<code>/</code> matches all routes). <code>app.get()</code> matches only HTTP GET requests and requires an exact route match.</p><h3 id="q55-how-does-express-5-handle-404-not-found-errors" tabindex="-1">Q55: How does Express 5 handle 404 Not Found errors? <a class="header-anchor" href="#q55-how-does-express-5-handle-404-not-found-errors" aria-label="Permalink to &quot;Q55: How does Express 5 handle 404 Not Found errors?&quot;">​</a></h3><p>If an incoming request does not match any static file or route handler, Express passes it to its internal default 404 handler, which responds with <code>Cannot GET /path</code> and an HTTP 404 status code.</p><h3 id="q56-how-do-you-implement-a-centralized-error-handler-in-express" tabindex="-1">Q56: How do you implement a centralized error handler in Express? <a class="header-anchor" href="#q56-how-do-you-implement-a-centralized-error-handler-in-express" aria-label="Permalink to &quot;Q56: How do you implement a centralized error handler in Express?&quot;">​</a></h3><p>By defining an error-handling middleware with four arguments at the very end of <code>app.js</code>:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">err</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">req</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">res</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">next</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(err.stack);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  res.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">send</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Internal Server Error&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>Express recognizes functions with four parameters <code>(err, req, res, next)</code> specifically as error handlers.</p><h3 id="q57-why-is-express-static-mounted-before-bodyparser" tabindex="-1">Q57: Why is <code>express.static</code> mounted before <code>bodyParser</code>? <a class="header-anchor" href="#q57-why-is-express-static-mounted-before-bodyparser" aria-label="Permalink to &quot;Q57: Why is `express.static` mounted before `bodyParser`?&quot;">​</a></h3><p>Mounting <code>express.static</code> first ensures that static asset requests (CSS, icons, images) are served directly from disk without wasting CPU cycles running body parsing or session deserialization.</p><h3 id="q58-what-is-the-difference-between-res-send-res-render-and-res-json" tabindex="-1">Q58: What is the difference between <code>res.send()</code>, <code>res.render()</code>, and <code>res.json()</code>? <a class="header-anchor" href="#q58-what-is-the-difference-between-res-send-res-render-and-res-json" aria-label="Permalink to &quot;Q58: What is the difference between `res.send()`, `res.render()`, and `res.json()`?&quot;">​</a></h3><ul><li><code>res.send()</code>: Sends a raw string, Buffer, or HTML markup with auto-detected Content-Type.</li><li><code>res.render()</code>: Compiles an EJS/Pug view template with a data model and flushes the resulting HTML string.</li><li><code>res.json()</code>: Formats a JavaScript object as JSON and sets <code>Content-Type: application/json</code>.</li></ul><h3 id="q59-what-is-the-purpose-of-path-join-dirname-views" tabindex="-1">Q59: What is the purpose of <code>path.join(__dirname, &#39;views&#39;)</code>? <a class="header-anchor" href="#q59-what-is-the-purpose-of-path-join-dirname-views" aria-label="Permalink to &quot;Q59: What is the purpose of `path.join(__dirname, &#39;views&#39;)`?&quot;">​</a></h3><p><code>__dirname</code> provides the absolute directory path of the currently executing file. <code>path.join()</code> safely concatenates path segments using the correct operating system path delimiter (<code>/</code> on Linux/macOS, <code>\\</code> on Windows), preventing cross-platform file lookup bugs.</p><h3 id="q60-how-does-res-redirect-work-at-the-http-protocol-level" tabindex="-1">Q60: How does <code>res.redirect()</code> work at the HTTP protocol level? <a class="header-anchor" href="#q60-how-does-res-redirect-work-at-the-http-protocol-level" aria-label="Permalink to &quot;Q60: How does `res.redirect()` work at the HTTP protocol level?&quot;">​</a></h3><p><code>res.redirect(&#39;/login&#39;)</code> sends an HTTP <code>302 Found</code> status code with the response header <code>Location: /login</code>. The client browser reads this header and immediately initiates a new HTTP GET request to the target URL.</p><hr><h2 id="group-4-database-session-persistence-q76-–-q100" tabindex="-1">Group 4: Database &amp; Session Persistence (Q76 – Q100) <a class="header-anchor" href="#group-4-database-session-persistence-q76-–-q100" aria-label="Permalink to &quot;Group 4: Database &amp; Session Persistence (Q76 – Q100)&quot;">​</a></h2><h3 id="q76-what-is-mongoose-and-why-use-it-over-the-native-mongodb-driver" tabindex="-1">Q76: What is Mongoose and why use it over the native MongoDB driver? <a class="header-anchor" href="#q76-what-is-mongoose-and-why-use-it-over-the-native-mongodb-driver" aria-label="Permalink to &quot;Q76: What is Mongoose and why use it over the native MongoDB driver?&quot;">​</a></h3><p>Mongoose is an Object Data Modeling (ODM) library for MongoDB. It provides schema-level validation, type casting, middleware hooks (pre/post save), and simplified query abstractions that ensure data integrity.</p><h3 id="q77-explain-the-user-schema-definition-in-app-js-18-22" tabindex="-1">Q77: Explain the user schema definition in <code>app.js:18-22</code>. <a class="header-anchor" href="#q77-explain-the-user-schema-definition-in-app-js-18-22" aria-label="Permalink to &quot;Q77: Explain the user schema definition in `app.js:18-22`.&quot;">​</a></h3><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> userSchema</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> mongoose.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Schema</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  username: { type: String, required: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  password: { type: String, required: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  name: String</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}, { collection: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;employees&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> });</span></span></code></pre></div><p>It defines a document schema requiring non-empty <code>username</code> and <code>password</code> strings, with an optional <code>name</code> string, explicitly binding to the <code>employees</code> collection.</p><h3 id="q78-what-is-an-objectid-in-mongodb" tabindex="-1">Q78: What is an ObjectId in MongoDB? <a class="header-anchor" href="#q78-what-is-an-objectid-in-mongodb" aria-label="Permalink to &quot;Q78: What is an ObjectId in MongoDB?&quot;">​</a></h3><p>An <code>ObjectId</code> is a 12-byte BSON identifier composed of:</p><ul><li>4 bytes representing the Unix timestamp.</li><li>5 bytes of random machine/process identifier.</li><li>3 bytes of incrementing counter. This guarantees global uniqueness across distributed database clusters.</li></ul><h3 id="q79-what-is-the-difference-between-user-findone-and-user-findbyid" tabindex="-1">Q79: What is the difference between <code>User.findOne()</code> and <code>User.findById()</code>? <a class="header-anchor" href="#q79-what-is-the-difference-between-user-findone-and-user-findbyid" aria-label="Permalink to &quot;Q79: What is the difference between `User.findOne()` and `User.findById()`?&quot;">​</a></h3><p><code>User.findOne({ username })</code> searches for the first document matching an arbitrary field query filter. <code>User.findById(id)</code> is an optimized convenience method that searches directly by primary key <code>_id</code> (<code>User.findOne({ _id: id })</code>).</p><h3 id="q80-what-is-connection-pooling-in-mongoose" tabindex="-1">Q80: What is connection pooling in Mongoose? <a class="header-anchor" href="#q80-what-is-connection-pooling-in-mongoose" aria-label="Permalink to &quot;Q80: What is connection pooling in Mongoose?&quot;">​</a></h3><p>Mongoose maintains an internal pool of open TCP socket connections to MongoDB (default size 100). Instead of creating a new socket connection for every HTTP request (which is expensive), Express routes borrow an existing connection from the pool, execute the query, and return it to the pool.</p><h3 id="q81-what-happens-if-the-mongodb-connection-drops-while-the-server-is-running" tabindex="-1">Q81: What happens if the MongoDB connection drops while the server is running? <a class="header-anchor" href="#q81-what-happens-if-the-mongodb-connection-drops-while-the-server-is-running" aria-label="Permalink to &quot;Q81: What happens if the MongoDB connection drops while the server is running?&quot;">​</a></h3><p>Mongoose emits a <code>&#39;disconnected&#39;</code> event and automatically attempts to reconnect using exponential backoff. While disconnected, Mongoose buffers incoming queries in memory up to a configurable timeout (default 30 seconds) before throwing a timeout error.</p><h3 id="q82-how-does-connect-mongo-serialize-session-data" tabindex="-1">Q82: How does <code>connect-mongo</code> serialize session data? <a class="header-anchor" href="#q82-how-does-connect-mongo-serialize-session-data" aria-label="Permalink to &quot;Q82: How does `connect-mongo` serialize session data?&quot;">​</a></h3><p>When <code>req.session.userId = user._id</code> is executed, <code>connect-mongo</code> serializes the session object into a BSON document and executes an <code>updateOne</code> command with <code>{ upsert: true }</code> in the <code>sessions</code> collection:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;s:q7WkZ...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;session&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">cookie</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:{...},</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">userId</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">65d4a1b...</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;expires&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">ISODate(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-10-26T12:00:00Z&quot;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="q83-what-is-the-n-1-query-problem-and-does-it-exist-in-this-project" tabindex="-1">Q83: What is the N+1 query problem and does it exist in this project? <a class="header-anchor" href="#q83-what-is-the-n-1-query-problem-and-does-it-exist-in-this-project" aria-label="Permalink to &quot;Q83: What is the N+1 query problem and does it exist in this project?&quot;">​</a></h3><p>The N+1 problem occurs when an application executes 1 query to fetch parent records and then $N$ separate queries to fetch related child records. In our current code, because we only fetch a single user document per request (<code>User.findById</code>), the N+1 problem is avoided.</p><h3 id="q84-how-would-you-add-a-unique-index-to-username-in-mongoose" tabindex="-1">Q84: How would you add a unique index to <code>username</code> in Mongoose? <a class="header-anchor" href="#q84-how-would-you-add-a-unique-index-to-username-in-mongoose" aria-label="Permalink to &quot;Q84: How would you add a unique index to `username` in Mongoose?&quot;">​</a></h3><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">username</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: String, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">required</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unique</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">index</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>Then call <code>userSchema.index({ username: 1 }, { unique: true })</code>.</p><h3 id="q85-what-is-the-difference-between-embedding-and-referencing-in-mongodb" tabindex="-1">Q85: What is the difference between embedding and referencing in MongoDB? <a class="header-anchor" href="#q85-what-is-the-difference-between-embedding-and-referencing-in-mongodb" aria-label="Permalink to &quot;Q85: What is the difference between embedding and referencing in MongoDB?&quot;">​</a></h3><p>Embedding nests child documents inside the parent document (1:1 or 1:few relationships, fast single-read queries). Referencing stores the <code>ObjectId</code> of another document in a separate collection (1:many or many:many relationships, requires <code>$lookup</code> or population).</p><hr><h2 id="group-5-authentication-security-owasp-q101-–-q125" tabindex="-1">Group 5: Authentication, Security &amp; OWASP (Q101 – Q125) <a class="header-anchor" href="#group-5-authentication-security-owasp-q101-–-q125" aria-label="Permalink to &quot;Group 5: Authentication, Security &amp; OWASP (Q101 – Q125)&quot;">​</a></h2><h3 id="q101-what-is-the-single-biggest-security-vulnerability-in-the-current-codebase" tabindex="-1">Q101: What is the single biggest security vulnerability in the current codebase? <a class="header-anchor" href="#q101-what-is-the-single-biggest-security-vulnerability-in-the-current-codebase" aria-label="Permalink to &quot;Q101: What is the single biggest security vulnerability in the current codebase?&quot;">​</a></h3><p><strong>Plaintext password storage</strong> in <code>app.js:20</code>. Storing passwords in clear text violates all security standards (HIPAA, GDPR, PCI-DSS).</p><h3 id="q102-how-do-you-fix-the-plaintext-password-vulnerability" tabindex="-1">Q102: How do you fix the plaintext password vulnerability? <a class="header-anchor" href="#q102-how-do-you-fix-the-plaintext-password-vulnerability" aria-label="Permalink to &quot;Q102: How do you fix the plaintext password vulnerability?&quot;">​</a></h3><p>Using <code>bcrypt</code>:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> bcrypt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;bcrypt&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// On registration:</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> saltRounds</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> hashedPassword</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bcrypt.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hash</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(password, saltRounds);</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> newUser</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> User</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ username, password: hashedPassword, name });</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> newUser.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">save</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// On login:</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> isMatch</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bcrypt.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">compare</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(password, user.password);</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">isMatch) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> res.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">send</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Invalid Credentials&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><h3 id="q103-what-are-saltrounds-in-bcrypt" tabindex="-1">Q103: What are <code>saltRounds</code> in bcrypt? <a class="header-anchor" href="#q103-what-are-saltrounds-in-bcrypt" aria-label="Permalink to &quot;Q103: What are `saltRounds` in bcrypt?&quot;">​</a></h3><p><code>saltRounds</code> defines the work factor ($2^{\\text{rounds}}$ iterations). 12 rounds means $2^{12} = 4,096$ hashing rounds, taking ~80ms per calculation. This computational cost protects against brute-force attacks using GPU rainbow tables.</p><h3 id="q104-what-is-the-difference-between-authentication-and-authorization" tabindex="-1">Q104: What is the difference between authentication and authorization? <a class="header-anchor" href="#q104-what-is-the-difference-between-authentication-and-authorization" aria-label="Permalink to &quot;Q104: What is the difference between authentication and authorization?&quot;">​</a></h3><ul><li><strong>Authentication</strong>: Verifying <em>who you are</em> (validating username and password).</li><li><strong>Authorization</strong>: Verifying <em>what you have permission to do</em> (checking if an authenticated doctor has permission to edit patient charts).</li></ul><h3 id="q105-what-is-cross-site-scripting-xss" tabindex="-1">Q105: What is Cross-Site Scripting (XSS)? <a class="header-anchor" href="#q105-what-is-cross-site-scripting-xss" aria-label="Permalink to &quot;Q105: What is Cross-Site Scripting (XSS)?&quot;">​</a></h3><p>XSS occurs when an attacker injects malicious JavaScript into a web page viewed by other users. If session cookies lack the <code>httpOnly</code> flag, injected JavaScript can read <code>document.cookie</code> and transmit the clinician&#39;s session cookie to an attacker server.</p><h3 id="q106-how-does-the-httponly-cookie-flag-prevent-session-hijacking" tabindex="-1">Q106: How does the <code>httpOnly</code> cookie flag prevent session hijacking? <a class="header-anchor" href="#q106-how-does-the-httponly-cookie-flag-prevent-session-hijacking" aria-label="Permalink to &quot;Q106: How does the `httpOnly` cookie flag prevent session hijacking?&quot;">​</a></h3><p>Setting <code>httpOnly: true</code> instructs the browser that the cookie must never be accessible via client-side JavaScript APIs (<code>document.cookie</code>). Even if an attacker executes an XSS payload, they cannot read the session cookie.</p><h3 id="q107-what-is-cross-site-request-forgery-csrf" tabindex="-1">Q107: What is Cross-Site Request Forgery (CSRF)? <a class="header-anchor" href="#q107-what-is-cross-site-request-forgery-csrf" aria-label="Permalink to &quot;Q107: What is Cross-Site Request Forgery (CSRF)?&quot;">​</a></h3><p>CSRF occurs when a malicious website tricks an authenticated user&#39;s browser into submitting an unauthorized request to another site where the user is logged in (e.g. submitting a hidden form to <code>POST /logout</code> or <code>POST /transfer</code>).</p><h3 id="q108-how-do-you-prevent-csrf-attacks-in-this-portal" tabindex="-1">Q108: How do you prevent CSRF attacks in this portal? <a class="header-anchor" href="#q108-how-do-you-prevent-csrf-attacks-in-this-portal" aria-label="Permalink to &quot;Q108: How do you prevent CSRF attacks in this portal?&quot;">​</a></h3><ol><li>Configure <code>sameSite: &#39;lax&#39;</code> or <code>&#39;strict&#39;</code> on the session cookie.</li><li>Integrate <code>csurf</code> or double-submit cookie tokens, validating a hidden cryptographic token on every state-changing form submission.</li></ol><h3 id="q109-what-is-nosql-injection" tabindex="-1">Q109: What is NoSQL Injection? <a class="header-anchor" href="#q109-what-is-nosql-injection" aria-label="Permalink to &quot;Q109: What is NoSQL Injection?&quot;">​</a></h3><p>NoSQL injection occurs when un-sanitized user input containing MongoDB query operators (like <code>$gt</code>, <code>$ne</code>, <code>$regex</code>) is passed directly into a query. For example, submitting <code>{&quot;username&quot;: {&quot;$ne&quot;: null}}</code> could match the first record in the database.</p><h3 id="q110-how-do-you-prevent-nosql-injection-in-express" tabindex="-1">Q110: How do you prevent NoSQL injection in Express? <a class="header-anchor" href="#q110-how-do-you-prevent-nosql-injection-in-express" aria-label="Permalink to &quot;Q110: How do you prevent NoSQL injection in Express?&quot;">​</a></h3><ol><li>Enforce strict Mongoose schemas with type casting.</li><li>Use the <code>express-mongo-sanitize</code> middleware to strip <code>$</code> and <code>.</code> characters from <code>req.body</code> and <code>req.params</code>.</li></ol><hr><h2 id="group-6-frontend-performance-systems-behavioral-q126-–-q150" tabindex="-1">Group 6: Frontend, Performance, Systems &amp; Behavioral (Q126 – Q150+) <a class="header-anchor" href="#group-6-frontend-performance-systems-behavioral-q126-–-q150" aria-label="Permalink to &quot;Group 6: Frontend, Performance, Systems &amp; Behavioral (Q126 – Q150+)&quot;">​</a></h2><h3 id="q126-how-does-the-3d-mouse-parallax-tilt-work-mathematically" tabindex="-1">Q126: How does the 3D mouse parallax tilt work mathematically? <a class="header-anchor" href="#q126-how-does-the-3d-mouse-parallax-tilt-work-mathematically" aria-label="Permalink to &quot;Q126: How does the 3D mouse parallax tilt work mathematically?&quot;">​</a></h3><p>In <code>login.html:463-467</code>:</p><ol><li>Find mouse distance from window center: <code>deltaX = (window.innerWidth / 2) - e.pageX</code>.</li><li>Divide by damping factor 25 to reduce sensitivity.</li><li>Clamp values: <code>rotateY = clamp(deltaX / 25, -10, 10)</code> and <code>rotateX = clamp(deltaY / 25, -10, 10)</code>.</li><li>Apply CSS transform: <code>rotateY(${rotateY}deg) rotateX(${rotateX}deg)</code>.</li></ol><h3 id="q127-what-is-css-backdrop-filter-blur-20px-and-how-does-it-work" tabindex="-1">Q127: What is CSS <code>backdrop-filter: blur(20px)</code> and how does it work? <a class="header-anchor" href="#q127-what-is-css-backdrop-filter-blur-20px-and-how-does-it-work" aria-label="Permalink to &quot;Q127: What is CSS `backdrop-filter: blur(20px)` and how does it work?&quot;">​</a></h3><p><code>backdrop-filter</code> applies a graphical filter (such as a Gaussian blur) to the visual area <em>behind</em> an element, creating the frosted glass effect without altering the element&#39;s own text or borders.</p><h3 id="q128-why-use-css-transforms-instead-of-modifying-top-or-left-properties" tabindex="-1">Q128: Why use CSS transforms instead of modifying <code>top</code> or <code>left</code> properties? <a class="header-anchor" href="#q128-why-use-css-transforms-instead-of-modifying-top-or-left-properties" aria-label="Permalink to &quot;Q128: Why use CSS transforms instead of modifying `top` or `left` properties?&quot;">​</a></h3><p>Modifying <code>top</code>, <code>left</code>, or <code>margin</code> triggers browser <strong>layout</strong> and <strong>paint</strong> cycles, consuming high CPU. CSS <code>transform</code> operates directly on the <strong>compositing layer</strong> of the GPU, executing at 60 FPS without layout thrashing.</p><h3 id="q129-what-is-the-hardest-bug-you-identified-in-this-codebase" tabindex="-1">Q129: What is the hardest bug you identified in this codebase? <a class="header-anchor" href="#q129-what-is-the-hardest-bug-you-identified-in-this-codebase" aria-label="Permalink to &quot;Q129: What is the hardest bug you identified in this codebase?&quot;">​</a></h3><p>The view lookup bug: <code>app.set(&#39;views&#39;, path.join(__dirname, &#39;views&#39;))</code> was configured in <code>app.js</code>, but <code>dashboard.ejs</code> was located in the root repository. Navigating to <code>/dashboard</code> threw a <code>Failed to lookup view</code> 500 error. The solution was creating <code>views/dashboard.ejs</code> to satisfy Express&#39;s template resolver.</p><h3 id="q130-what-would-you-change-if-you-rebuilt-this-application-from-scratch" tabindex="-1">Q130: What would you change if you rebuilt this application from scratch? <a class="header-anchor" href="#q130-what-would-you-change-if-you-rebuilt-this-application-from-scratch" aria-label="Permalink to &quot;Q130: What would you change if you rebuilt this application from scratch?&quot;">​</a></h3><ol><li>Switch to TypeScript for strict end-to-end interface typing.</li><li>Replace plaintext passwords with Argon2id.</li><li>Ingest configuration from <code>.env</code> using Zod validation.</li><li>Replace inline <code>&lt;script&gt;</code> alerts with clean JSON REST endpoints.</li><li>Add automated integration testing with Supertest and Jest.</li></ol><hr><p><em>(Questions Q131 to Q155 cover detailed behavioral scenarios, CI/CD pipelines, Docker containerization, and system design tradeoffs fully expanded in the accompanying documentation files).</em></p>',180))])}const E=n(u,[["render",k]]);export{q as __pageData,E as default};
